function makeSortable(ul, { getHandle }) {
  let active = null;
  const items = () => Array.from(ul.querySelectorAll('li'));

  function startDrag(e, li) {
    // only primary button
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const handle = getHandle(li);
    if (!handle.contains(e.target)) return; // when handle-only
    e.preventDefault();
    const rect = li.getBoundingClientRect();
    const ph = document.createElement('li');
    ph.className = 'disc-item disc-ghost-placeholder';
    ph.style.height = rect.height + 'px';
    // insert placeholder before li
    ul.insertBefore(ph, li);
    li.classList.add('is-dragging');
    li.style.width = rect.width + 'px';
    li.style.position = 'fixed';
    li.style.left = rect.left + 'px';
    li.style.top = rect.top + 'px';
    li.style.margin = '0';
    li.style.zIndex = 1000;
    active = { li, ph, ul, pointerId: e.pointerId, offsetX: e.clientX - rect.left, offsetY: e.clientY - rect.top, startY: e.clientY, moved: false };
    handle.setPointerCapture?.(e.pointerId); // capture on the handle or the li
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
  }
