(() => {
  'use strict';

  const doc = document;
  const root = doc.getElementById('wizardmodal');
  const dialog = root.querySelector('.disc-modal__dialog');
  const scroller = root.querySelector('.disc-modal__body');
  const tabsEl = root.querySelector('.disc-tabs');
  const progressEl = root.querySelector('.disc-progress');
  const actionsEl = root.querySelector('.disc-actions');
  const tabs = Array.from(root.querySelectorAll('.disc-tab'));
  const panes = Array.from(root.querySelectorAll('.disc-pane'));
  const lists = Array.from(root.querySelectorAll('ul.disc-list'));
  const bar = doc.getElementById('discProgress');
  const btnPrev = root.querySelector('[data-disc-prev]');
  const btnNext = root.querySelector('[data-disc-next]');
  const btnFinish = root.querySelector('[data-disc-finish]');
  const resultEl = doc.getElementById('discResult');
  const btnRestart = doc.getElementById('btnRestart');

  const STEP_COUNT = panes.length;
  let step = 0;
  let isOpen = false;
  let inResult = false;

  // Save initial order for restarting
  const initialOrder = new Map();
  lists.forEach(ul => initialOrder.set(ul, Array.from(ul.querySelectorAll('li.disc-item'))));

  /* ---------- modal management ---------- */
  const docEl = doc.documentElement;
  const savedOverflow = { html: '', body: '' };
  function lockScroll(on) {
    if (on) {
      savedOverflow.html = docEl.style.overflow;
      savedOverflow.body = doc.body.style.overflow;
      docEl.style.overflow = 'hidden';
      doc.body.style.overflow = 'hidden';
    } else {
      docEl.style.overflow = savedOverflow.html;
      doc.body.style.overflow = savedOverflow.body;
    }
  }

  function openModal() {
    if (isOpen) return;
    if (inResult) resetToTest();
    isOpen = true;
    root.classList.add('active');
    root.setAttribute('aria-hidden', 'false');
    if ('inert' in root) root.inert = false; — wait, initial inert true; set to false on open
    lockScroll(true);
    render();
    doc.addEventListener('keydown', onKeyDown);
    dialog.querySelector('.disc-modal__close').focus();
  }
  function closeModal() {
    if (!isOpen) return;
    isOpen = false;
    root.classList.remove('active');
    root.setAttribute('aria-hidden', 'true');
    if ('inert' in root) root.inert = true;
    lockScroll(false);
    doc.removeEventListener('keydown', onKeyDown);
  }
