```js
  function onKeyDown(e) {
    if (e.key === 'Escape') { e.preventDefault(); closeModal(); return; }
    if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
      const li = (e.target && e.target.closest) ? e.target.closest('li.disc-item') : null;
      if (!li || !li.parentElement.classList.contains('disc-list')) return;
      e.preventDefault();
      moveItem(li, e.key === 'ArrowUp' ? -1 : 1);
      li.focus();
    }
  }
