  /* ---------- drag & drop (self-written, works on mouse and touch, no libraries) ---------- */
  const coarse = typeof matchMedia === 'function' && matchMedia('(pointer: coarse)').matches;

  function attachDnD(ul) {
    let drag = null;
    const items = () => Array.from(ul.querySelectorAll('li.disc-item')).filter(li => !li.classList.contains('disc-placeholder'));

    function place(li, e) { li.style.left = (e.clientX - drag.dx) + 'px'; li.style.top = (e.clientY - drag.dy) + 'px'; }

    function autoScroll(clientY) {
      const r = scroller.getBoundingClientRect();
      const M = 48, V = 14;
      if (clientY < r.top + M) scroller.scrollTop -= V;
      else if (clientY > r.bottom - M) scroller.scrollTop += V;
    }

    function updateOrder(clientY) {
      const kids = Array.from(ul.children);
      let anchor = null;
      for (const el of kids) {
        if (el === drag.li || el === drag.ph) continue;
        const r = el.getBoundingClientRect();
        if (clientY < r.top + r.height / 2) { anchor = el; break; }
      }
      const phIdx = kids.indexOf(drag.ph);
      const wantIdx = anchor ? kids.indexOf(anchor) : kids.length;
      if (wantIdx !== phIdx && wantIdx !== phIdx + 1) ul.insertBefore(drag.ph, anchor);
    }

    function onStart(e) {
      const li = e.currentTarget;
      if (drag) return;
      if (e.pointerType === 'mouse' && e.button !== 0) return;
      if (coarse && !e.target.closest('.disc-handle')) return;
      e.preventDefault();
      const rect = li.getBoundingClientRect();
      const ph = doc.createElement('li');
      ph.className = 'disc-item disc-placeholder';
      ph.setAttribute('aria-hidden', 'true');
      ph.style.height = rect.height + 'px';
      ul.insertBefore(ph, li);
      li.classList.add('is-dragging');
      li.style.position = 'fixed';
      li.style.left = rect.left + 'px';
      li.style.top = rect.top + 'px';
      li.style.width = rect.width + 'px';
      li.style.margin = '0';
      li.style.zIndex = '200';
      li.style.pointerEvents = 'none';
      drag = { li, ph, id: e.pointerId, dx: e.clientX - rect.left, dy: e.clientY - rect.top, moved: false };
      li.setPointerCapture && li.setPointerCapture(e.pointerId);
      doc.addEventListener('pointermove', onMove, { passive: false });
      doc.addEventListener('pointerup', onEnd, false);
      doc.addEventListener('pointercancel', onEnd, false);
    }

    function onMove(e) {
      if (!drag || e.pointerId !== drag.id) return;
      e.preventDefault();
      drag.moved = true;
      autoScroll(e.clientY);
      drag.li.style.left = (e.clientX - drag.dx) + 'px';
      drag.li.style.top = (e.clientY - drag.dy) + 'px';
      updateOrder(e.clientY);
    }

    function onEnd(e) {
      if (!drag || e.pointerId !== drag.id) return;
      const { li, ph } = drag;
      drag = null;
      doc.removeEventListener('pointermove', onMove);
      doc.removeEventListener('pointerup', onEnd);
      doc.removeEventListener('pointercancel', onEnd);
      ul.insertBefore(li, ph);
      ph.remove();
      li.classList.remove('is-dragging');
      li.style.cssText = '';
    }

    ul.querySelectorAll('li.disc-item').forEach(li => {
      li.addEventListener('pointerdown', onStart);
    });
  }
  lists.forEach(attachDnD);
